from __future__ import annotations


COMMON_STYLE = r"""
:root{color-scheme:light;--bg:#f4f6fb;--surface:#fff;--surface-2:#f8f9fc;--text:#121826;--muted:#687086;--line:#e4e7ef;--accent:#5b5ce2;--accent-2:#7c4dff;--good:#16845b;--warn:#ad6a00;--bad:#c7354d;--shadow:0 18px 50px rgba(39,45,77,.08);--radius:22px}
*{box-sizing:border-box}html{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}body{margin:0;min-height:100vh;background:radial-gradient(circle at 15% -10%,rgba(124,77,255,.12),transparent 30%),radial-gradient(circle at 100% 0,rgba(91,92,226,.1),transparent 34%),var(--bg)}button,input,select{font:inherit}button{cursor:pointer}.shell{width:min(1180px,calc(100% - 32px));margin:0 auto;padding:28px 0 64px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.brand{display:flex;align-items:center;gap:13px}.logo{width:44px;height:44px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(145deg,var(--accent),var(--accent-2));box-shadow:0 12px 30px rgba(91,92,226,.28);color:#fff;font-weight:850;letter-spacing:-1px}.brand h1{font-size:20px;margin:0}.brand p{font-size:13px;color:var(--muted);margin:3px 0 0}.pill{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);background:rgba(255,255,255,.78);backdrop-filter:blur(16px);border-radius:999px;padding:9px 12px;font-size:13px;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 5px rgba(22,132,91,.1)}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{background:var(--surface);border:1px solid rgba(228,231,239,.85);border-radius:var(--radius);box-shadow:var(--shadow);padding:22px}.hero{grid-column:span 12;display:flex;justify-content:space-between;align-items:flex-end;gap:20px;overflow:hidden;position:relative}.hero:after{content:"";position:absolute;width:260px;height:260px;border-radius:50%;right:-80px;top:-135px;background:linear-gradient(145deg,rgba(91,92,226,.18),rgba(124,77,255,.04));pointer-events:none}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}.hero h2{font-size:clamp(28px,4vw,46px);line-height:1.05;letter-spacing:-.045em;margin:10px 0 12px}.hero p{margin:0;color:var(--muted);max-width:660px;line-height:1.7}.actions{display:flex;gap:10px;flex-wrap:wrap;position:relative;z-index:1}.btn{border:0;border-radius:14px;padding:11px 15px;font-weight:720;transition:.18s ease;display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none}.btn:hover{transform:translateY(-1px)}.btn.primary{background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;box-shadow:0 10px 22px rgba(91,92,226,.23)}.btn.secondary{background:var(--surface-2);color:var(--text);border:1px solid var(--line)}.btn.danger{background:#fff2f4;color:var(--bad);border:1px solid #ffd9df}.stats{grid-column:span 12;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:18px}.stat .label{color:var(--muted);font-size:13px}.stat .value{font-size:23px;font-weight:800;margin-top:8px;letter-spacing:-.03em}.lottery{grid-column:span 6}.lottery-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.lottery h3{margin:0;font-size:22px}.sub{color:var(--muted);font-size:13px;margin-top:5px}.numbers{display:flex;flex-wrap:wrap;gap:7px;margin:18px 0}.num{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;background:var(--surface-2);border:1px solid var(--line);font-weight:760}.forecast{padding:14px 0;border-top:1px solid var(--line)}.forecast:first-of-type{border-top:0}.forecast-title{display:flex;justify-content:space-between;gap:12px;font-size:14px;font-weight:700}.forecast-meta{font-size:12px;color:var(--muted);margin-top:6px;line-height:1.5}.empty{padding:18px;border:1px dashed var(--line);border-radius:15px;color:var(--muted);text-align:center}.status-good{color:var(--good)}.status-warn{color:var(--warn)}.status-bad{color:var(--bad)}.sidebar-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px}.sidebar{position:sticky;top:20px;height:max-content;background:rgba(255,255,255,.82);backdrop-filter:blur(18px);border:1px solid var(--line);border-radius:22px;padding:12px;box-shadow:var(--shadow)}.nav-item{width:100%;border:0;background:transparent;color:var(--muted);padding:13px 14px;border-radius:14px;text-align:left;font-weight:700;margin:2px 0}.nav-item.active{background:#efefff;color:var(--accent)}.panel{display:none}.panel.active{display:block}.panel-title{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:16px}.panel-title h2{font-size:28px;margin:0;letter-spacing:-.035em}.panel-title p{color:var(--muted);margin:5px 0 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:8px}.field.full{grid-column:1/-1}.field label{font-size:13px;color:var(--muted);font-weight:700}.input{width:100%;border:1px solid var(--line);background:var(--surface-2);border-radius:14px;padding:12px 13px;color:var(--text);outline:none;transition:.16s}.input:focus{border-color:rgba(91,92,226,.55);box-shadow:0 0 0 4px rgba(91,92,226,.1);background:#fff}.switch-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:15px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}.switch{position:relative;width:48px;height:28px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;background:#c9ceda;border-radius:999px;transition:.2s}.slider:before{content:"";position:absolute;width:22px;height:22px;left:3px;top:3px;border-radius:50%;background:#fff;box-shadow:0 3px 8px rgba(0,0,0,.18);transition:.2s}.switch input:checked+.slider{background:var(--accent)}.switch input:checked+.slider:before{transform:translateX(20px)}.preset-row{display:flex;gap:8px;flex-wrap:wrap}.chip{border:1px solid var(--line);background:var(--surface-2);border-radius:999px;padding:8px 11px;font-size:12px;font-weight:700;color:var(--muted)}.chip:hover{border-color:var(--accent);color:var(--accent)}.notice{padding:13px 14px;border-radius:14px;background:#f0f1ff;color:#4748b9;font-size:13px;line-height:1.6;border:1px solid #dfe0ff}.log{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;white-space:pre-wrap;word-break:break-word;background:#111522;color:#d9dff4;border-radius:16px;padding:16px;min-height:100px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}.table th{color:var(--muted);font-weight:700}.toast{position:fixed;right:20px;bottom:20px;max-width:min(420px,calc(100% - 40px));background:#161b2b;color:#fff;border-radius:15px;padding:13px 16px;box-shadow:0 18px 45px rgba(0,0,0,.25);opacity:0;transform:translateY(12px);pointer-events:none;transition:.2s;z-index:99}.toast.show{opacity:1;transform:none}.toast.error{background:#7c2334}.mobile-nav{display:none}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.login-card{width:min(430px,100%);background:rgba(255,255,255,.9);backdrop-filter:blur(18px);border:1px solid var(--line);border-radius:28px;padding:28px;box-shadow:0 28px 80px rgba(38,43,76,.14)}.login-card h1{font-size:30px;margin:18px 0 8px;letter-spacing:-.04em}.login-card p{color:var(--muted);line-height:1.6;margin:0 0 22px}.login-card .btn{width:100%;margin-top:12px}.footer{color:var(--muted);font-size:12px;text-align:center;margin-top:26px;line-height:1.7}
@media(max-width:860px){.shell{width:min(100% - 22px,720px);padding-top:18px}.topbar{margin-bottom:16px}.hero{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr 1fr}.lottery{grid-column:span 12}.sidebar-layout{display:block}.sidebar{display:none}.mobile-nav{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:10px;right:10px;bottom:10px;z-index:50;background:rgba(255,255,255,.9);backdrop-filter:blur(20px);border:1px solid var(--line);border-radius:18px;padding:6px;box-shadow:0 18px 50px rgba(35,40,70,.18)}.mobile-nav .nav-item{text-align:center;font-size:12px;padding:10px 4px;margin:0}.admin-shell{padding-bottom:100px}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.panel-title{align-items:flex-start;flex-direction:column}.table-wrap{overflow:auto}.topbar .pill.hide-mobile{display:none}}
@media(max-width:520px){.stats{grid-template-columns:1fr}.card{padding:18px}.hero h2{font-size:31px}.logo{width:40px;height:40px}.brand p{display:none}.actions{width:100%}.actions .btn{flex:1}.num{width:31px;height:31px;border-radius:10px}.lottery h3{font-size:20px}}
"""


def public_page() -> str:
    return f"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f6fb"><title>天机云端</title><style>{COMMON_STYLE}</style></head><body>
<div class="shell"><header class="topbar"><div class="brand"><div class="logo">天</div><div><h1>天机云端</h1><p>持续同步、首次冻结与真实验证</p></div></div><div class="pill"><span class="dot" id="statusDot"></span><span id="statusText">连接中</span></div></header>
<div class="grid"><section class="card hero"><div><div class="eyebrow">Tianji Cloud</div><h2>服务器负责持续运行，<br>手机保留本地能力。</h2><p>云端全天同步开奖与生成前向档案；服务器失效时，Android 仍可使用本机统计、手机直连 AI 和本地历史。</p></div><div class="actions"><a class="btn primary" href="/admin">管理控制台</a><a class="btn secondary" href="/docs">API 文档</a></div></section>
<section class="stats" id="stats"><div class="stat"><div class="label">服务状态</div><div class="value">读取中</div></div><div class="stat"><div class="label">后台任务</div><div class="value">读取中</div></div><div class="stat"><div class="label">云端 AI</div><div class="value">读取中</div></div><div class="stat"><div class="label">服务版本</div><div class="value">—</div></div></section><div id="lotteries" style="display:contents"></div></div>
<div class="footer">随机开奖不可可靠预测。本服务用于统计实验、首次结果冻结与目标期验证，不承诺盈利或必中。</div></div>
<script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt=n=>n?new Date(n).toLocaleString('zh-CN',{hour12:false}):'—';
async function refresh(){{try{{const r=await fetch('/v1/public/overview',{{cache:'no-store'}});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();document.getElementById('statusText').textContent=d.health.status==='ok'?'运行正常':'状态异常';document.getElementById('statusDot').style.background=d.health.status==='ok'?'var(--good)':'var(--bad)';document.getElementById('stats').innerHTML=`<div class="stat"><div class="label">服务状态</div><div class="value status-good">${{esc(d.health.database)}}</div></div><div class="stat"><div class="label">后台任务</div><div class="value ${{d.health.worker==='ok'?'status-good':'status-warn'}}">${{esc(d.health.worker)}}</div></div><div class="stat"><div class="label">云端 AI</div><div class="value">${{d.ai.configured?esc(d.ai.model):'未配置'}}</div></div><div class="stat"><div class="label">服务版本</div><div class="value">${{esc(d.health.version)}}</div></div>`;document.getElementById('lotteries').innerHTML=d.lotteries.map(x=>`<section class="card lottery"><div class="lottery-head"><div><h3>${{esc(x.name)}}</h3><div class="sub">最新期 ${{esc(x.latest_period||'等待同步')}} · 更新 ${{fmt(x.synced_at_epoch_ms)}}</div></div><div class="pill">目标期 ${{esc(x.next_period||'待同步')}}</div></div><div class="numbers">${{(x.numbers||[]).map(n=>`<span class="num">${{n}}</span>`).join('')}}</div>${{x.forecasts.length?x.forecasts.map(f=>`<div class="forecast"><div class="forecast-title"><span>${{f.source==='ai'?'云端 AI':'本机云端'}} · 第 ${{f.position+1}} 名</span><span>${{f.top6_hit===true?'命中':f.top6_hit===false?'未中':'待开奖'}}</span></div><div class="forecast-meta">六码 ${{f.top6.join(' ')}} · 模型 ${{esc(f.model)}} · 目标期 ${{esc(f.target_period)}}</div></div>`).join(''):'<div class="empty">等待下一期前向档案</div>'}}</section>`).join('')}}catch(e){{document.getElementById('statusText').textContent='连接失败';document.getElementById('statusDot').style.background='var(--bad)'}}}}
refresh();setInterval(refresh,30000);
</script></body></html>"""


def login_page(configured: bool) -> str:
    message = "输入部署时设置的管理密码。" if configured else "服务器还没有设置管理密码，请先运行更新脚本完成一次初始化。"
    disabled = "" if configured else "disabled"
    return f"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 · 天机控制台</title><style>{COMMON_STYLE}</style></head><body><div class="login-wrap"><main class="login-card"><div class="logo">天</div><h1>进入控制台</h1><p>{message}</p><form id="loginForm"><div class="field"><label>管理密码</label><input class="input" id="password" type="password" minlength="8" autocomplete="current-password" placeholder="至少 8 个字符" {disabled}></div><button class="btn primary" id="loginBtn" {disabled}>登录</button></form><div class="footer"><a href="/" style="color:var(--accent);text-decoration:none">返回公开状态页</a></div></main></div><div class="toast" id="toast"></div><script>
const toast=(m,e=false)=>{{const t=document.getElementById('toast');t.textContent=m;t.className='toast show'+(e?' error':'');setTimeout(()=>t.className='toast',2600)}};
document.getElementById('loginForm').addEventListener('submit',async e=>{{e.preventDefault();const b=document.getElementById('loginBtn');b.disabled=true;try{{const r=await fetch('/admin/api/login',{{method:'POST',headers:{{'Content-Type':'application/json','X-Tianji-Admin':'1'}},body:JSON.stringify({{password:document.getElementById('password').value}})}});const d=await r.json();if(!r.ok)throw new Error(d.detail||'登录失败');location.href='/admin';}}catch(err){{toast(err.message,true);b.disabled=false}}}});
</script></body></html>"""


def admin_page() -> str:
    return f"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f6fb"><title>天机控制台</title><style>{COMMON_STYLE}</style></head><body><div class="shell admin-shell"><header class="topbar"><div class="brand"><div class="logo">天</div><div><h1>天机控制台</h1><p>无需 SSH 的云端管理面板</p></div></div><div style="display:flex;gap:8px"><div class="pill hide-mobile"><span class="dot" id="topDot"></span><span id="topStatus">读取中</span></div><button class="btn secondary" id="logoutBtn">退出</button></div></header>
<div class="sidebar-layout"><aside class="sidebar"><button class="nav-item active" data-panel="overview">总览</button><button class="nav-item" data-panel="ai">AI 模型</button><button class="nav-item" data-panel="records">预测档案</button><button class="nav-item" data-panel="security">安全</button></aside><main>
<section class="panel active" id="panel-overview"><div class="panel-title"><div><h2>运行总览</h2><p>服务、数据库、后台任务和最近一次同步。</p></div><button class="btn primary" id="runBtn">立即执行一轮</button></div><div class="stats" id="adminStats"></div><div class="grid" id="adminLotteries" style="margin-top:16px"></div><div class="card" style="margin-top:16px"><div class="panel-title"><div><h2 style="font-size:20px">最近状态</h2><p>后台任务心跳与最近 AI 错误。</p></div></div><div class="log" id="runtimeLog">读取中…</div></div></section>
<section class="panel" id="panel-ai"><div class="panel-title"><div><h2>AI 模型</h2><p>保存后立即生效，下一次后台任务直接使用新配置，不需要重启或 SSH。</p></div></div><div class="card"><div class="switch-row"><div><strong>启用云端 AI</strong><div class="sub">关闭后仍保留本机云端统计预测</div></div><label class="switch"><input id="aiEnabled" type="checkbox"><span class="slider"></span></label></div><div class="notice" style="margin:14px 0">API Key 只保存在服务器数据目录的 600 权限文件中。密钥输入框留空会保留当前密钥，不会回显完整内容。</div><div class="preset-row" style="margin-bottom:14px"><button class="chip" data-preset="deepseek-pro">DeepSeek V4 Pro</button><button class="chip" data-preset="deepseek-flash">DeepSeek V4 Flash</button><button class="chip" data-preset="deepseek-custom">DeepSeek 自定义</button><button class="chip" data-preset="openai">OpenAI Responses</button></div><div class="form-grid"><div class="field full"><label>接口地址</label><input class="input" id="aiEndpoint" inputmode="url" placeholder="https://api.example.com/v1/chat/completions"></div><div class="field"><label>模型名</label><input class="input" id="aiModel" list="modelList" placeholder="填写或读取模型列表"><datalist id="modelList"></datalist></div><div class="field"><label>超时时间</label><select class="input" id="aiTimeout"><option value="45">45 秒</option><option value="90">90 秒</option><option value="120">120 秒</option><option value="180">180 秒</option><option value="300">300 秒</option></select></div><div class="field full"><label>API Key</label><input class="input" id="aiKey" type="password" autocomplete="new-password" placeholder="留空保留当前密钥"></div></div><div class="sub" id="keyHint" style="margin-top:10px">当前密钥：读取中</div><div class="actions" style="margin-top:18px"><button class="btn primary" id="saveAiBtn">保存并立即生效</button><button class="btn secondary" id="testAiBtn">测试连接</button><button class="btn secondary" id="modelsBtn">读取模型</button></div><div class="log" id="aiResult" style="margin-top:16px;min-height:68px">等待操作</div></div></section>
<section class="panel" id="panel-records"><div class="panel-title"><div><h2>预测档案</h2><p>服务器首次冻结结果和按目标期结算状态。</p></div></div><div class="card table-wrap"><table class="table"><thead><tr><th>彩种</th><th>目标期</th><th>来源 / 模型</th><th>名次与六码</th><th>结果</th></tr></thead><tbody id="recordsBody"></tbody></table></div></section>
<section class="panel" id="panel-security"><div class="panel-title"><div><h2>安全设置</h2><p>修改网页登录密码，不影响 SSH 或服务器 root 密码。</p></div></div><div class="card"><div class="form-grid"><div class="field"><label>当前管理密码</label><input class="input" id="oldPassword" type="password" autocomplete="current-password"></div><div class="field"><label>新管理密码</label><input class="input" id="newPassword" type="password" minlength="8" autocomplete="new-password"></div></div><button class="btn primary" id="passwordBtn" style="margin-top:16px">更新管理密码</button></div></section>
</main></div></div>
<nav class="mobile-nav"><button class="nav-item active" data-panel="overview">总览</button><button class="nav-item" data-panel="ai">AI</button><button class="nav-item" data-panel="records">档案</button><button class="nav-item" data-panel="security">安全</button></nav><div class="toast" id="toast"></div>
<script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const fmt=n=>n?new Date(n).toLocaleString('zh-CN',{{hour12:false}}):'—';let state=null;
const toast=(m,e=false)=>{{const t=document.getElementById('toast');t.textContent=m;t.className='toast show'+(e?' error':'');setTimeout(()=>t.className='toast',2800)}};
async function api(path,options={{}}){{const r=await fetch(path,{{cache:'no-store',...options,headers:{{'X-Tianji-Admin':'1',...(options.headers||{{}})}}}});if(r.status===401){{location.href='/admin';throw new Error('登录已过期')}}const d=await r.json().catch(()=>({{}}));if(!r.ok)throw new Error(d.detail||('HTTP '+r.status));return d}}
function setPanel(name){{document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id==='panel-'+name));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));window.scrollTo({{top:0,behavior:'smooth'}})}}document.querySelectorAll('.nav-item').forEach(x=>x.addEventListener('click',()=>setPanel(x.dataset.panel)));
function render(d){{state=d;document.getElementById('topStatus').textContent=d.health.worker==='ok'?'运行正常':'需要检查';document.getElementById('topDot').style.background=d.health.worker==='ok'?'var(--good)':'var(--warn)';document.getElementById('adminStats').innerHTML=`<div class="stat"><div class="label">API</div><div class="value status-good">${{esc(d.health.status)}}</div></div><div class="stat"><div class="label">数据库</div><div class="value status-good">${{esc(d.health.database)}}</div></div><div class="stat"><div class="label">后台任务</div><div class="value ${{d.health.worker==='ok'?'status-good':'status-warn'}}">${{esc(d.health.worker)}}</div></div><div class="stat"><div class="label">当前模型</div><div class="value">${{d.ai.configured?esc(d.ai.model):'仅本机'}}</div></div>`;document.getElementById('adminLotteries').innerHTML=d.lotteries.map(x=>`<section class="card lottery"><div class="lottery-head"><div><h3>${{esc(x.name)}}</h3><div class="sub">最新期 ${{esc(x.latest_period||'等待同步')}} · ${{fmt(x.synced_at_epoch_ms)}}</div></div><div class="pill">目标期 ${{esc(x.next_period||'待同步')}}</div></div><div class="numbers">${{(x.numbers||[]).map(n=>`<span class="num">${{n}}</span>`).join('')}}</div><div class="sub">历史 ${{x.draw_count}} 期 · 最新档案 ${{x.forecasts.length}} 条</div></section>`).join('');document.getElementById('runtimeLog').textContent=JSON.stringify({{heartbeat:d.heartbeat,ai_errors:d.ai_errors}},null,2);document.getElementById('aiEnabled').checked=d.ai.enabled;document.getElementById('aiEndpoint').value=d.ai.endpoint||'';document.getElementById('aiModel').value=d.ai.model||'';document.getElementById('aiTimeout').value=String(d.ai.timeout_seconds||120);document.getElementById('keyHint').textContent='当前密钥：'+d.ai.api_key_hint;document.getElementById('recordsBody').innerHTML=d.records.length?d.records.map(r=>`<tr><td>${{esc(r.lottery_name)}}</td><td>${{esc(r.target_period)}}</td><td>${{r.source==='ai'?'AI':'本机'}}<br><span class="sub">${{esc(r.model)}}</span></td><td>第 ${{r.position+1}} 名<br><span class="sub">${{r.top6.join(' ')}}</span></td><td>${{r.top6_hit===true?'<span class="status-good">命中</span>':r.top6_hit===false?'<span class="status-bad">未中</span>':'待开奖'}}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">暂无档案</td></tr>'}}
async function load(){{try{{render(await api('/admin/api/state'))}}catch(e){{toast(e.message,true)}}}}
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',e=>{{e.preventDefault();const p=b.dataset.preset;if(p==='deepseek-pro'){{aiEndpoint.value='https://api.deepseek.com/chat/completions';aiModel.value='deepseek-v4-pro'}}else if(p==='deepseek-flash'){{aiEndpoint.value='https://api.deepseek.com/chat/completions';aiModel.value='deepseek-v4-flash'}}else if(p==='deepseek-custom'){{aiEndpoint.value='https://api.deepseek.com/chat/completions';aiModel.focus()}}else if(p==='openai'){{aiEndpoint.value='https://api.openai.com/v1/responses';aiModel.value=''}}}}));
function configPayload(){{return {{enabled:aiEnabled.checked,endpoint:aiEndpoint.value.trim(),model:aiModel.value.trim(),api_key:aiKey.value||null,timeout_seconds:Number(aiTimeout.value)}}}}
saveAiBtn.onclick=async()=>{{saveAiBtn.disabled=true;try{{const d=await api('/admin/api/ai',{{method:'PUT',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(configPayload())}});aiKey.value='';toast('AI 配置已保存并立即生效');await load();}}catch(e){{toast(e.message,true)}}finally{{saveAiBtn.disabled=false}}}};
testAiBtn.onclick=async()=>{{testAiBtn.disabled=true;aiResult.textContent='正在测试连接…';try{{const d=await api('/admin/api/ai/test',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(configPayload())}});aiResult.textContent=JSON.stringify(d,null,2);toast('连接测试完成')}}catch(e){{aiResult.textContent=e.message;toast(e.message,true)}}finally{{testAiBtn.disabled=false}}}};
modelsBtn.onclick=async()=>{{modelsBtn.disabled=true;aiResult.textContent='正在读取模型列表…';try{{const d=await api('/admin/api/ai/models',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(configPayload())}});modelList.innerHTML=d.models.map(m=>`<option value="${{esc(m)}}"></option>`).join('');aiResult.textContent=d.message+'\n'+d.models.join('\n');toast('已读取模型列表')}}catch(e){{aiResult.textContent=e.message;toast(e.message,true)}}finally{{modelsBtn.disabled=false}}}};
runBtn.onclick=async()=>{{runBtn.disabled=true;try{{await api('/admin/api/run',{{method:'POST'}});toast('后台任务已开始，稍后自动刷新');setTimeout(load,5000)}}catch(e){{toast(e.message,true)}}finally{{setTimeout(()=>runBtn.disabled=false,2500)}}}};
passwordBtn.onclick=async()=>{{passwordBtn.disabled=true;try{{await api('/admin/api/password',{{method:'PUT',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{current_password:oldPassword.value,new_password:newPassword.value}})}});oldPassword.value='';newPassword.value='';toast('管理密码已更新')}}catch(e){{toast(e.message,true)}}finally{{passwordBtn.disabled=false}}}};
logoutBtn.onclick=async()=>{{await api('/admin/api/logout',{{method:'POST'}}).catch(()=>{{}});location.href='/admin'}};
load();setInterval(load,30000);
</script></body></html>"""
